param([ValidateSet('Debug','Release')][string]$Configuration='Debug',[switch]$Run)
$ErrorActionPreference='Stop';$r=$PSScriptRoot;$b=Join-Path $r build;$v=Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe';$vs=& $v -latest -products * -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath;$c=Join-Path $vs 'Common7\IDE\CommonExtensions\Microsoft\CMake\CMake\bin\cmake.exe'; & $c -S $r -B $b -G 'Visual Studio 18 2026' -A x64;if($LASTEXITCODE){throw 'Configure failed'};& $c --build $b --config $Configuration;if($LASTEXITCODE){throw 'Build failed'};& $c --build $b --config $Configuration --target RUN_TESTS;if($LASTEXITCODE){throw 'Tests failed'};if($Run){& (Join-Path $b "$Configuration\arrays.exe")}
